import { render } from '@solidjs/web';
import { createSignal, Show, Switch, Match } from 'solid-js';

function Weather() {
  const [temp, setTemp] = createSignal(12);

  return (
    <>
      <input
        type="range"
        min="-10"
        max="40"
        value={temp()}
        onInput={(event) => setTemp(Number(event.currentTarget.value))}
      />{' '}
      {temp()}°C
      {temp() < 0 ? <p>Frost warning!</p> : <p>No frost tonight.</p>}
      {temp() > 25 ? <p>Hot</p> : temp() > 10 ? <p>Mild</p> : <p>Cold</p>}
    </>
  );
}

render(() => <Weather />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { createSignal, Show, Switch, Match } from 'solid-js';

function Weather() {
  const [temp, setTemp] = createSignal(12);

  return (
    <>
      <input
        type="range"
        min="-10"
        max="40"
        value={temp()}
        onInput={(event) => setTemp(Number(event.currentTarget.value))}
      />{' '}
      {temp()}°C
      <Show when={temp() < 0} fallback={<p>No frost tonight.</p>}>
        <p>Frost warning!</p>
      </Show>
      <Switch fallback={<p>Cold</p>}>
        <Match when={temp() > 25}>
          <p>Hot</p>
        </Match>
        <Match when={temp() > 10}>
          <p>Mild</p>
        </Match>
      </Switch>
    </>
  );
}

render(() => <Weather />, document.getElementById('app'));
